const orders=[
{id:'1042',name:'Mariana Costa',initial:'MC',device:'iPhone 13',issue:'Troca de tela',status:'Em reparo',cls:'purple',tech:'Lucas Almeida',date:'Hoje, 17:00',value:450},
{id:'1041',name:'Rafael Santos',initial:'RS',device:'Dell Inspiron 15',issue:'Não liga',status:'Em análise',cls:'',tech:'Ana Souza',date:'04 nov, 14:00',value:180},
{id:'1040',name:'Camila Oliveira',initial:'CO',device:'Samsung Galaxy A54',issue:'Troca de bateria',status:'Pronto para entrega',cls:'green',tech:'Lucas Almeida',date:'Hoje, 16:00',value:220},
{id:'1039',name:'Pedro Lima',initial:'PL',device:'MacBook Air M1',issue:'Limpeza e manutenção',status:'Aguardando aprovação',cls:'yellow',tech:'Ana Souza',date:'05 nov, 12:00',value:350},
{id:'1038',name:'Juliana Alves',initial:'JA',device:'iPad 9ª geração',issue:'Conector de carga',status:'Em reparo',cls:'purple',tech:'Lucas Almeida',date:'04 nov, 18:00',value:280},
{id:'1037',name:'Bruno Martins',initial:'BM',device:'Motorola Edge 40',issue:'Diagnóstico de placa',status:'Aguardando aprovação',cls:'yellow',tech:'Ana Souza',date:'06 nov, 15:00',value:320}];
const money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const navs=[['dashboard','◫','Visão geral'],['orders','▤','Ordens de serviço','24'],['clients','♧','Clientes'],['devices','▱','Aparelhos'],['finance','▥','Financeiro'],['settings','⚙','Configurações']];
let current='dashboard',mode='table',query='',status='Todos os status';
const content=document.querySelector('#content');
const badge=o=>`<span class="badge ${o.cls}">${o.status}</span>`;
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.style.display='none',4200)}
function stats(){return `<div class="stats">${[['Ordens em andamento','24','▤','+4','em relação à semana anterior'],['Aguardando aprovação','08','◷','3','orçamentos aguardam há mais de 24h'],['Prontos para entrega','12','✓','5','serviços concluídos hoje'],['Receita do mês','R$ 8.450','↗','+12,8%','em relação ao mês anterior']].map((s,i)=>`<div class="stat"><div class="label">${s[0]}<span class="si" style="color:${['#a4a2ff','#dfb778','#69cbb0','#7db2ff'][i]}">${s[2]}</span></div><strong>${s[1]}</strong><small><em>${s[3]}</em>${s[4]}</small></div>`).join('')}</div>`}
function table(list){return `<div class="tablewrap"><table><thead><tr><th>ORDEM</th><th>CLIENTE</th><th>APARELHO / SERVIÇO</th><th>STATUS</th><th>PREVISÃO</th><th></th></tr></thead><tbody>${list.map(o=>`<tr data-order="${o.id}" tabindex="0" role="button" aria-label="Ver ordem ${o.id}"><td class="orderid">#OS-${o.id}</td><td><div class="clientcell"><span class="initial">${o.initial}</span>${o.name}</div></td><td>${o.device}<small>${o.issue}</small></td><td>${badge(o)}</td><td>${o.date}</td><td>↗</td></tr>`).join('')}</tbody></table></div>${!list.length?'<div class="empty">Nenhuma ordem encontrada. Ajuste a busca ou o filtro.</div>':''}`}
function dashboard(){content.innerHTML=stats()+`<div class="twocol"><section class="panel"><div class="panelhead"><div><h2>Movimento da assistência</h2><p>Entrada e conclusão de ordens nesta semana</p></div><div class="legend"><span>Recebidas</span><span>Concluídas</span></div></div><div class="chart"><div class="bars">${[[45,30],[70,50],[55,43],[85,65],[62,48],[38,28],[26,18]].map(a=>`<div class="bargroup"><div class="bar" style="height:${a[0]}%" title="${a[0]/5} recebidas"></div><div class="bar alt" style="height:${a[1]}%" title="${a[1]/5} concluídas"></div></div>`).join('')}</div><div class="chartlabels">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(x=>`<span>${x}</span>`).join('')}</div></div></section><section class="panel"><div class="panelhead"><div><h2>Serviços por etapa</h2><p>Uma visão do seu fluxo de trabalho</p></div><span class="muted">◌</span></div><div class="ringrow"><div class="ring" role="img" aria-label="Distribuição ilustrativa de 44 serviços por etapa"><strong>44<small>serviços ativos</small></strong></div><div class="ringlegend">${[['Em reparo','16','#7b7beb'],['Em análise','08','#568be0'],['Aguardando','08','#d4a55d'],['Prontos','12','#55b8aa']].map(a=>`<div><span class="bullet" style="background:${a[2]}"></span>${a[0]}<b>${a[1]}</b></div>`).join('')}</div></div></section></div><section class="panel"><div class="panelhead"><div><h2>Ordens recentes</h2><p>Acompanhe os últimos atendimentos</p></div><button class="textbutton" data-go="orders">Ver todas as ordens ↗</button></div>${table(orders.slice(0,4))}<div class="tablefoot"><span>Exibindo 4 ordens de exemplo</span><span>Atualizado na demonstração</span></div></section><div class="below"><section class="panel"><div class="panelhead"><h2>Atividade recente</h2><span class="muted" style="font-size:10px">Hoje</span></div><div class="activity"><div><span class="initial">LA</span><p>Lucas concluiu o reparo da <span class="orderid">#OS-1040</span><small>Troca de bateria · Samsung Galaxy A54 · há 12 min</small></p></div><div><span class="initial">AS</span><p>Ana enviou um orçamento para aprovação<small>#OS-1039 · MacBook Air M1 · há 35 min</small></p></div><div><span class="initial">FR</span><p>Nova ordem de serviço registrada<small>#OS-1042 · Mariana Costa · há 1 hora</small></p></div></div></section><section class="panel"><div class="panelhead"><h2>Precisa da sua atenção</h2><span class="badge yellow">3 pendências</span></div><div class="task"><span>◷</span><div><strong>Orçamento sem retorno</strong><small>#OS-1039 · Pedro Lima</small></div><b>Há 2 dias</b></div><div class="task"><span>▱</span><div><strong>Aparelho pronto para retirada</strong><small>#OS-1040 · Camila Oliveira</small></div><b>Hoje</b></div><div class="task"><span>◇</span><div><strong>Confirmar peça de reposição</strong><small>#OS-1038 · Juliana Alves</small></div><b>Hoje</b></div></section></div>`}
function filtered(){return orders.filter(o=>(status==='Todos os status'||o.status===status)&&[o.name,o.id,o.device,o.issue].some(s=>s.toLowerCase().includes(query.toLowerCase())))}
function orderBody(){const list=filtered();return mode==='table'?table(list):`<div class="kanban">${['Em análise','Aguardando aprovação','Em reparo','Pronto para entrega'].map(s=>`<div class="column"><h3>${s} <span>${list.filter(o=>o.status===s).length}</span></h3>${list.filter(o=>o.status===s).map(o=>`<div class="ticket" data-order="${o.id}" tabindex="0" role="button"><small>#OS-${o.id}</small><strong>${o.device}</strong><p>${o.issue}</p><div class="bottom"><span>${o.name.split(' ')[0]}</span><span>${money(o.value)}</span></div></div>`).join('')}</div>`).join('')}</div>`}
function renderOrders(){content.innerHTML=`<section class="panel"><div class="panelhead"><div><h2>Central de ordens</h2><p>Acompanhe os serviços em lista ou por etapa</p></div><span class="badge gray">6 exemplos</span></div><div class="toolbar"><label class="search" style="margin:0">⌕<input id="search" placeholder="Buscar OS, cliente ou aparelho…" aria-label="Buscar ordens"></label><select id="filter" aria-label="Filtrar por status">${['Todos os status','Em análise','Aguardando aprovação','Em reparo','Pronto para entrega'].map(s=>`<option ${s===status?'selected':''}>${s}</option>`).join('')}</select><div class="tabs"><button data-mode="table" class="${mode==='table'?'active':''}">☷ Lista</button><button data-mode="kanban" class="${mode==='kanban'?'active':''}">▥ Quadro</button></div></div><div id="orderbody">${orderBody()}</div><div class="tablefoot"><span id="count">${filtered().length} ordens de exemplo</span><span>Sem alterações persistidas</span></div></section>`;document.querySelector('#search').value=query;document.querySelector('#search').oninput=e=>{query=e.target.value;document.querySelector('#orderbody').innerHTML=orderBody();document.querySelector('#count').textContent=filtered().length+' ordens de exemplo'};document.querySelector('#filter').onchange=e=>{status=e.target.value;renderOrders()}}
function clients(){content.innerHTML=`<section class="panel"><div class="panelhead"><div><h2>Seus clientes</h2><p>Relacionamentos e histórico de atendimento</p></div><button class="secondary" data-demo="Cadastro de cliente: prévia visual, sem gravação.">＋ Novo cliente</button></div><div class="toolbar"><label class="search" style="margin:0">⌕<input id="clientsearch" placeholder="Buscar cliente pelo nome…" aria-label="Buscar cliente"></label></div><div class="tablewrap"><table><thead><tr><th>CLIENTE</th><th>CONTATO ILUSTRATIVO</th><th>ÚLTIMO APARELHO</th><th>ORDENS</th><th></th></tr></thead><tbody id="clientrows"></tbody></table></div></section>`;const rows=q=>{const l=orders.filter(o=>o.name.toLowerCase().includes(q.toLowerCase()));document.querySelector('#clientrows').innerHTML=l.map((o,i)=>`<tr data-order="${o.id}"><td><div class="clientcell"><span class="initial">${o.initial}</span>${o.name}</div></td><td>Contato de demonstração<small>Nenhum dado pessoal real</small></td><td>${o.device}</td><td>${i+1} atendimento(s)</td><td>Ver histórico ↗</td></tr>`).join('')||'<tr><td colspan="5">Nenhum cliente encontrado.</td></tr>'};rows('');document.querySelector('#clientsearch').oninput=e=>rows(e.target.value)}
function devices(){content.innerHTML=`<section class="panel"><div class="panelhead"><div><h2>Aparelhos em atendimento</h2><p>Identificação e vínculo com as ordens de serviço</p></div><span class="badge gray">Inventário ilustrativo</span></div><div class="tablewrap"><table><thead><tr><th>APARELHO</th><th>CLIENTE</th><th>IDENTIFICAÇÃO</th><th>ESTADO ATUAL</th><th>ORDEM</th></tr></thead><tbody>${orders.map((o,i)=>`<tr data-order="${o.id}"><td>${o.device}<small>${o.issue}</small></td><td>${o.name}</td><td>DEMO-00${i+1}</td><td>${badge(o)}</td><td class="orderid">#OS-${o.id} ↗</td></tr>`).join('')}</tbody></table></div></section>`}
function finance(){content.innerHTML=`<div class="stats">${[['Receita do mês','R$ 8.450'],['A receber','R$ 2.380'],['Despesas previstas','R$ 1.820'],['Saldo estimado','R$ 6.630']].map(x=>`<div class="stat"><div class="label">${x[0]}</div><strong>${x[1]}</strong><small>Valores ilustrativos · novembro</small></div>`).join('')}</div><section class="panel"><div class="panelhead"><div><h2>Recebimentos previstos</h2><p>Prévia financeira dos atendimentos</p></div><button class="secondary" data-demo="Relatório demonstrativo: não há dados financeiros reais para exportar.">↓ Exportar</button></div><div class="tablewrap"><table><thead><tr><th>REFERÊNCIA</th><th>CLIENTE</th><th>DESCRIÇÃO</th><th>VALOR</th><th>SITUAÇÃO</th></tr></thead><tbody>${orders.map(o=>`<tr data-order="${o.id}"><td class="orderid">#OS-${o.id}</td><td>${o.name}</td><td>${o.issue}</td><td>${money(o.value)}</td><td><span class="badge ${o.id==='1040'?'green':'yellow'}">${o.id==='1040'?'Recebido':'Previsto'}</span></td></tr>`).join('')}</tbody></table></div></section>`}
function settings(){content.innerHTML=`<section class="panel"><div class="panelhead"><div><h2>Preferências da assistência</h2><p>Visualização das configurações do workspace</p></div><span class="badge purple">Demonstração</span></div><div class="settings"><div class="formgrid"><label>Nome da assistência<input value="Assistência Central"></label><label>Unidade<input value="São Gonçalo"></label></div>${[['Notificações de ordens','Alertas visuais sobre novos atendimentos.'],['Lembretes de orçamento','Destaque para aprovações pendentes.'],['Resumo da operação','Visão diária dos serviços da equipe.']].map(x=>`<div class="settingsrow"><div>${x[0]}<p>${x[1]}</p></div><button class="switch" role="switch" aria-checked="true" aria-label="${x[0]}"></button></div>`).join('')}<div class="infobox">A seleção de unidade é ilustrativa. Este protótipo não implementa autenticação, permissões ou isolamento de dados.</div><button class="primary" data-demo="Preferências simuladas. Nenhuma configuração foi salva.">Simular salvamento</button></div></section>`}
function go(id){current=id;document.querySelectorAll('#nav button').forEach(b=>{b.classList.toggle('active',b.dataset.go===id);b.setAttribute('aria-current',b.dataset.go===id?'page':'false')});const label=navs.find(n=>n[0]===id)[2];document.querySelector('#crumb').textContent=label;document.querySelector('#eyebrow').textContent=id==='dashboard'?'TERÇA-FEIRA, 03 DE NOVEMBRO':'ASSISTÊNCIA CENTRAL / OPERAÇÃO';document.querySelector('#title').textContent=id==='dashboard'?'Bom trabalho, Filipe ✦':label;document.querySelector('#subtitle').textContent={dashboard:'Tudo o que sua assistência precisa, no mesmo fluxo.',orders:'Cada reparo com contexto, do recebimento à entrega.',clients:'Conheça quem confia o próximo reparo à sua equipe.',devices:'Todos os equipamentos, com histórico e identificação.',finance:'Uma visão clara dos valores de cada atendimento.',settings:'Seu espaço de trabalho, do seu jeito.'}[id];({dashboard,orders:renderOrders,clients,devices,finance,settings}[id])();document.querySelector('#sidebar').classList.remove('open');}
function detail(id){const o=orders.find(x=>x.id===id);document.querySelector('#detailcontent').innerHTML=`<div class="dialoghead"><div><div class="eyebrow">ORDEM DE SERVIÇO</div><h2>#OS-${o.id}</h2></div><button class="close" aria-label="Fechar">×</button></div><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:22px">${badge(o)}<span class="muted">Previsão: ${o.date}</span></div><div class="detailgrid"><div class="detailbox"><h3>CLIENTE</h3><p>${o.name}<br><span class="muted">Atendimento de demonstração</span></p></div><div class="detailbox"><h3>APARELHO</h3><p>${o.device}<br><span class="muted">Identificação: DEMO-${o.id}</span></p></div><div class="detailbox"><h3>PROBLEMA RELATADO</h3><p>${o.issue}</p></div><div class="detailbox"><h3>RESPONSÁVEL / ORÇAMENTO</h3><p>${o.tech}<br><span style="color:#b1a7ff">${money(o.value)}</span></p></div></div><h3 style="font-size:13px;margin-top:25px">Histórico do atendimento</h3><div class="timeline"><p>Aparelho recebido e cadastrado<small>02 nov · 09:15 · Filipe Rosa</small></p><p>Diagnóstico técnico iniciado<small>02 nov · 11:30 · ${o.tech}</small></p><p>${o.status}<small>03 nov · 14:20 · Última atualização ilustrativa</small></p></div><div class="dialogactions"><button class="secondary" data-demo="Prévia de impressão. A OS é fictícia e nenhum documento foi emitido.">Imprimir OS</button><button class="primary" data-demo="Mudança de etapa simulada. O protótipo não altera a ordem.">Avançar etapa →</button></div>`;document.querySelector('#detail').showModal()}
document.querySelector('#nav').innerHTML=navs.map(n=>`<button data-go="${n[0]}"><span class="ni">${n[1]}</span>${n[2]}${n[3]?`<small>${n[3]}</small>`:''}</button>`).join('');
document.addEventListener('click',e=>{const goButton=e.target.closest('[data-go]');if(goButton)go(goButton.dataset.go);const row=e.target.closest('[data-order]');if(row)detail(row.dataset.order);const mb=e.target.closest('[data-mode]');if(mb){mode=mb.dataset.mode;renderOrders()}const demo=e.target.closest('[data-demo]');if(demo)toast(demo.dataset.demo);if(e.target.closest('.close'))e.target.closest('dialog').close();const sw=e.target.closest('.switch');if(sw){sw.classList.toggle('off');sw.setAttribute('aria-checked',!sw.classList.contains('off'))}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-order]')){e.preventDefault();detail(e.target.dataset.order)}});
document.querySelector('#new').onclick=()=>document.querySelector('#create').showModal();document.querySelector('#newform').onsubmit=e=>{e.preventDefault();document.querySelector('#create').close();e.target.reset();toast('Abertura simulada com sucesso. Nenhuma ordem foi criada ou salva.')};document.querySelector('#bell').onclick=()=>toast('3 alertas de exemplo: orçamento pendente, aparelho para retirada e peça para confirmar.');document.querySelector('#workspace').onclick=()=>toast('Assistência Central · Unidade São Gonçalo. A troca de unidade é apenas ilustrativa.');document.querySelector('#menu').onclick=()=>document.querySelector('#sidebar').classList.toggle('open');document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d)d.close()}));go('dashboard');
